def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_aggressive = 0
    weak_opp = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                weak_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0)
                prev_bids.append(b)
                if b >= 0.75 * DAILY_SALARY and opp.get('budget', 0) > 2 * DAILY_SALARY:
                    rich_aggressive += 1

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.25))

    capacity = supply / float(WATER_REQ)
    scarcity = capacity < (len(alive) + 1)
    very_tight = capacity < len(alive)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0

    emergency = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1

    if emergency:
        bid = max(DAILY_SALARY * 0.92, highest_prev + 2.0)
    elif very_tight:
        if highest_prev >= DAILY_SALARY * 0.85:
            bid = DAILY_SALARY * (0.88 if pressured else 0.52)
        else:
            bid = max(DAILY_SALARY * (0.72 if pressured else 0.46), highest_prev + 1.25)
    elif scarcity:
        if rich_aggressive >= 2 and hp > 4:
            bid = DAILY_SALARY * 0.34
        else:
            bid = max(DAILY_SALARY * (0.58 if pressured else 0.38), min(highest_prev + 1.0, DAILY_SALARY * 0.76))
    else:
        bid = DAILY_SALARY * (0.42 if pressured else 0.22)

    if weak_opp >= 2 and hp > 4 and not emergency:
        bid *= 0.9

    if day >= 8 and hp <= 4:
        bid = max(bid, DAILY_SALARY * 0.78)

    if budget < DAILY_SALARY:
        bid = min(bid, max(0.0, budget * (0.72 if pressured else 0.5)))
    else:
        reserve = max(0.0, (10 - day) * DAILY_SALARY * 0.18)
        bid = min(bid, max(0.0, budget - reserve))

    if budget <= 0:
        return 0.0
    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive_ids = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_ids.append(oid)

    if not alive_ids:
        # If alone, conserve budget while still paying enough when supply is tight
        base = DAILY_SALARY * 0.35
        if my_status['no_water_days'] >= 2:
            base = DAILY_SALARY * 0.75
        return float(min(my_status['budget'], base))

    # Immediate reaction to yesterday's bids (only previous_trace)
    yesterday_bids = []
    for oid in alive_ids:
        prev = opponents_status[oid].get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: how many full water requirements are available
    # Use int() for any indexing; here we only compute scalars.
    supply_units = supply / float(WATER_REQ)

    # Determine aggressiveness
    # If someone previously bid near our daily salary, they likely overbid to secure water.
    # We counter with a moderate bid to avoid getting outbid while not matching extremes.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 0.35
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        pressure = 0.20
    else:
        pressure = 0.10

    # HP and no-water urgency
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])

    urgency = 0.0
    if hp <= 2:
        urgency = 0.65
    elif hp <= 4:
        urgency = 0.45
    elif no_water_days >= 3:
        urgency = 0.45
    elif no_water_days >= 2:
        urgency = 0.25
    else:
        urgency = 0.10

    # Base bid scales with supply tightness: tighter supply => higher bid
    # supply_units ~ 1.66 to 2.77 for 15-25 with WATER_REQ=9
    # We'll map to a tightness factor.
    tightness = 0.0
    if supply <= MIN_SUPPLY + 1e-6:
        tightness = 0.40
    elif supply >= MAX_SUPPLY - 1e-6:
        tightness = 0.10
    else:
        # linear between MIN_SUPPLY and MAX_SUPPLY
        tightness = 0.40 - 0.30 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # Final target fraction of daily salary
    frac = 0.30 + pressure + urgency + tightness

    # If supply is relatively abundant, reduce bids unless we're in danger
    if supply_units >= 2.4 and hp > 4:
        frac -= 0.10

    # Clamp fraction
    if frac < 0.20:
        frac = 0.20
    if frac > 0.95:
        frac = 0.95

    bid = DAILY_SALARY * frac

    # Never exceed budget
    if my_status['budget'] <= 0:
        return 0.0
    if bid > my_status['budget']:
        bid = float(my_status['budget'])

    # If very low budget, still try a small amount to avoid total starvation
    if my_status['budget'] < DAILY_SALARY * 0.25:
        # If we're already on multiple no-water days, spend more
        if no_water_days >= 2:
            bid = float(min(my_status['budget'], DAILY_SALARY * 0.55))
        else:
            bid = float(min(my_status['budget'], DAILY_SALARY * 0.20))

    return float(bid)
